const products = $input.first().json;
const prefs = $('Webhook').first().json;
const keywords = prefs.keywords || [];

function score(p) {
  const r = p.rating || 0;
  const c = Math.log((p.rating_count || 0) + 1);
  const kw = keywords.some(k =>
    (p.product_name || '').toLowerCase().includes(k.toLowerCase()) ||
    (p.about_product || '').toLowerCase().includes(k.toLowerCase())
  ) ? 1.5 : 1.0;
  return r * c * kw;
}

const ranked = [...products].sort((a, b) => score(b) - score(a));
return [{ json: { ranked } }];

const { ranked } = $input.first().json;
const top3 = ranked.slice(0, 3);

const comparison = [
  { attribute: 'Price (₹)',  values: top3.map(p => p.discounted_price?.toFixed(0) ?? 'N/A') },
  { attribute: 'Rating',     values: top3.map(p => p.rating?.toFixed(1) ?? 'N/A') },
  { attribute: 'Reviews',    values: top3.map(p => p.rating_count?.toLocaleString() ?? 'N/A') },
  { attribute: 'Discount',   values: top3.map(p => p.discount_percentage ? `${p.discount_percentage}%` : 'N/A') },
];

return [{ json: { products: top3, comparison } }];
